# Latest author request: Figure 1 uses HC / AD / Other everywhere.
for(s in SPACES)local({space<-s;id<-paste0('Fig1',LETTERS[match(space,SPACES)+1]);sid<-paste0('FigS14',LETTERS[match(space,SPACES)]);registry[[id]]<<-registry[[sid]];source_tables[[id]]<<-source_tables[[sid]];captions[[id]]<<-captions[[sid]];original_fn<-registry[[id]];registry[[id]]<<-function()original_fn()+labs(y='SSB Ri')+scale_x_discrete(labels=setNames(c('HC\nn=144','AD\nn=89','Other\nn=28'),G3))})
d<-ri[,.(sample_id,pathology_group,region,fraction)];st<-rbindlist(lapply(SPACES,function(s){dd<-d[region==s];rbindlist(lapply(list(c(G3[2],G3[1]),c(G3[3],G3[1]),c(G3[2],G3[3])),function(g){v<-dd[pathology_group%in%g];data.table(region=s,group1=g[1],group2=g[2],n=nrow(v),P=wilcox.test(fraction~pathology_group,v,exact=FALSE)$p.value)}))}));st[,FDR:=p.adjust(P,'BH')]
register('Fig1A',d,st,function()ggplot(d,aes(fraction,factor(pathology_group,levels=rev(G3)),fill=pathology_group,colour=pathology_group))+geom_boxplot(width=.55,outlier.shape=NA,alpha=.2,linewidth=LWD)+geom_point(position=position_jitter(height=.12,width=0,seed=SEED),size=.7,alpha=.5)+facet_wrap(~region,nrow=1,scales='free_x')+scale_fill_manual(values=COL)+scale_colour_manual(values=COL)+scale_y_discrete(labels=setNames(c('HC (144)','AD (89)','Other (28)'),G3))+scale_x_continuous(labels=scales::label_percent(accuracy=.1))+labs(x='Fraction of complete-library SSB positions',y=NULL)+theme_pub()+theme(legend.position='none'),'Fractions of complete-library SSB positions overlapping four globally nonredundant annotation classes. HC n=144, AD n=89, Other n=28; boxes show medians/IQR, whiskers observations within 1.5 IQR, and points all participants. A position counts once per class, but classes overlap and fractions do not sum to one. Twelve descriptive pairwise Wilcoxon tests and their correction are supplied, separately from the gene-feature models.','三组完整文库位点在四类全局非冗余注释中的比例。HC144、AD89、Other28；箱体中位数/IQR、1.5IQR须线和全部点。同位点每类最多一次，类别重叠，不要求比例和为1。12个描述性Wilcoxon两两检验及校正另附，与基因特征模型区分。')
d<-ri[region=='GENE'];co<-cor.test(d$Ri,d$D,method='spearman',exact=FALSE);st<-data.table(n=nrow(d),rho=unname(co$estimate),P=co$p.value);register('Fig1F',d[,.(sample_id,pathology_group,Ri,D)],st,function()ggplot(d,aes(D/1e6,Ri,colour=pathology_group))+geom_point(size=1.2,alpha=.7)+scale_colour_manual(values=COL,labels=setNames(c('HC','AD','Other'),G3))+guides(colour=guide_legend(nrow=1))+labs(x='Library SSB positions (millions)',y='GENE Ri',subtitle=sprintf('n=261; rho=%.5f; P%s',st$rho,if(st$P==0)'<2.2e-16'else paste0('=',fmtp(st$P))))+theme_pub(),'GENE Ri versus complete-library deduplicated position yield for all 261 participants, colored HC/AD/Other. The pooled two-sided Spearman coefficient describes yield dependence, not AD-specific biology.','261例GENE Ri与完整文库去重位点数，按HC/AD/Other着色。全队列双侧Spearman描述产量依赖，不是AD特异生物机制。')
# Save the former two-source technical attenuation and age forest in SI.
registry$FigS25A<-registry$Fig1G;source_tables$FigS25A<-source_tables$Fig1G;captions$FigS25A<-captions$Fig1G
registry$FigS25B<-registry$Fig1H;source_tables$FigS25B<-source_tables$Fig1H;captions$FigS25B<-captions$Fig1H
participant_overrides$FigS25A<-participant_overrides$FigS25B<-m[complete_primary==TRUE,.(sample_id)];supp_layout$S25<-c('FigS25A','FigS25B')
d<-rm[model=='B_technical'];st<-copy(d);register('Fig1G',d,st,function(){x<-copy(d);x[,comparison:=factor(contrast,levels=c('Positive_vs_HC','Negative_vs_HC','Positive_vs_Negative'),labels=c('AD vs HC','Other vs HC','AD vs Other'))];ggplot(x,aes(beta,factor(region,levels=rev(SPACES))))+geom_vline(xintercept=0,linetype=2,colour='#888888',linewidth=LWD)+geom_errorbar(aes(xmin=CI_low,xmax=CI_high),orientation='y',width=.2,linewidth=LWD)+geom_point(colour='#3C5488',size=1.8)+facet_wrap(~comparison,nrow=1,scales='free_x')+labs(x='Adjusted log2(Ri + 1) difference (95% CI)',y=NULL)+theme_pub()},'All twelve regional contrasts from the three-group age/sex/technical model: HC142, AD89, Other28, n=259. Points are log2(Ri+1) coefficients and lines are 95% CI; the null reference is zero. Complete nominal and adjusted P values accompany the figure. No corrected regional contrast passed the prespecified threshold.','三组年龄/性别/技术调整模型全部12个区域对比：HC142、AD89、Other28，共259例。点为log2(Ri+1)系数，线为95%CI，零为参照；完整原始和校正P随图，预定校正阈值下无区域发现。');participant_overrides$Fig1G<-m[complete_primary==TRUE,.(sample_id)]
d<-m[!is.na(age_years),.(sample_id,pathology_group,age_years)];st<-rbindlist(lapply(list(c(G3[2],G3[1]),c(G3[3],G3[1]),c(G3[2],G3[3])),function(g){dd<-d[pathology_group%in%g];data.table(group1=g[1],group2=g[2],n=nrow(dd),P=wilcox.test(age_years~pathology_group,dd,exact=FALSE)$p.value)}));st[,FDR:=p.adjust(P,'BH')];register('Fig1H',d,st,function()box(d,'age_years',group='pathology_group',title='Age distribution')+labs(y='Age (years)'),'Observed ages in the three research groups: HC143, AD89 and Other28 (260 participants); one HC age is missing. Points are participants, boxes median/IQR and whiskers 1.5 IQR. Three descriptive two-sided Wilcoxon comparisons are supplied; continuous-age adjustment remains in the molecular models.','三组实测年龄：HC143、AD89、Other28，共260例，一例HC年龄缺失。点为参与者，中位数/IQR箱体和1.5IQR须线。三项描述性双侧Wilcoxon另附，分子模型仍调整连续年龄。');participant_overrides$Fig1H<-d[,.(sample_id)]
